  "globals.rhythm": "Toolbar / unit rhythm",
  "globals.rhythmLead":
    "Card / Collapsible body stacks sibling units with `unit-stack-gap` (16dp). Related control + note → `ControlBlock` (`field-hint-gap` 8dp — tighter). On a single ControlRow the hint docks in the label column; ToggleGroup centers on name + hint (not a full-bleed next row). Padded Surface is a form host like Card body. Prefer `ControlStack` + `ControlRow`, `.fynns-unit-stack`, and these tokens over raw `--fynns-space-*`.",
  "globals.rhythmSampleTitle": "Rhythm sample",
  "globals.rhythmClusterHelp":
    "Optional `.fynns-control-cluster` for side-by-side end-labeled switches (toolbar). Preferences / settings Cards should use one track-only Switch per ControlRow instead — see rows above.",
  "globals.rhythmRowContent": "Content",
  "globals.rhythmRowBehavior": "Behavior",
  "globals.rhythmShowIcon": "Option A",
  "globals.rhythmShowActions": "Option B",
  "globals.rhythmDisabled": "Disable cluster",
  "globals.rhythmCompactLabel": "Compact",
  "globals.rhythmControlBlockHint":
    "When on, chrome uses denser padding. Wrap the Switch and this note in ControlBlock — do not leave the paragraph as a Card sibling.",
  "globals.rhythmFieldHintSample":
    "Standalone FieldHint for app-owned columns (same muted caption as Input supportingText).",
  "globals.rhythmTokenUnit":
    "Between stacked units / Card body siblings / `.fynns-unit-stack` (16dp — larger than field-hint).",
  "globals.rhythmTokenFieldLabel":
    "FieldHeader / label row → control (12dp): `.fynns-field-block__main` — roomier than control→hint.",
  "globals.rhythmTokenFieldHint":
    "Control → supporting/error note (8dp): Input / ControlBlock / FieldBlock description — not the same as unit-stack.",
  "globals.rhythmTokenStack":
    "Between ControlRows inside one ControlStack (8dp — tighter than unit-stack so a following ControlBlock reads as the next unit).",
  "globals.rhythmTokenRowCol": "Label | controls when the row is horizontal.",
  "globals.rhythmTokenRow": "Label above controls when the row stacks (narrow).",
  "globals.rhythmTokenCluster": "Sibling switches / chips inside one controls cluster.",
  "globals.rhythmSurfaceHelp":
    "Padded Surface + single-row ControlBlock: supporting copy stays in the name column; the ToggleGroup / action cluster is vertically centered on name + hint — even when this column is narrow. **Do not** put a sibling FieldHint that only lists the ToggleGroup option labels (information redundancy — failure mode: CONSUMER_TREATY FieldHint restates ToggleGroup / Tabs labels).",
  "globals.rhythmCatalogHelp":
    "**Catalog list chrome (hard ≥ 0.5.266):** standalone `ControlRow` (not inside `ControlStack`) fills the host — label `1fr`, IconButtons in one `.fynns-control-cluster` hug the trailing edge (**md** default — match List trailing on the same page). **Do not** park bare `{n}` / `.length` `.fynns-table-meta` beside Plus/import/clear, and **do not** bake `(N)` / `N/M` into the label — List / EmptyState already show cardinality (**information redundancy**; CONSUMER_TREATY ControlRow unsolicited item count). Counts only when the product explicitly requires them. Do not leave a content-sized island with actions mid-left.",
  "globals.rhythmCatalogLabel": "Servers",
  "globals.rhythmCatalogBulk": "Bulk select",
  "globals.rhythmCatalogRefresh": "Refresh list",
  "globals.rhythmCatalogAdd": "Add server",
  "globals.rhythmEndAlignHelp":
    "Action footer with no visible name: one `.fynns-control-cluster--end-align` (`justify-content: flex-end` — IconButton strips need no `__grow`). Use `__grow` only when a leading Select / meta must fill leftover. Never `ControlRow` with empty `label=\"\"` (fake label column / mid-left island). **Busy (hard):** click either button — **at most one** `loading` ring; the sibling stays `disabled` without a second spinner. Never bind the same `busy` to every `loading`.",
  "globals.rhythmEndAlignIconHelp":
    "Icon-only end-align strip: Tooltip → IconButton siblings stay 40dp circles (not crushed ellipses on the full-width row).",
  "globals.rhythmEndAlignIconOpenTip": "Open destination folder",
  "globals.rhythmEndAlignIconPrimaryTip": "Start archive copy",
  "globals.rhythmEndAlignSecondary": "Secondary",
  "globals.rhythmEndAlignPrimary": "Primary action",
  "globals.rhythmServiceHelp":
    "**Service / process / CLI probe (hard):** `ControlRow` `label` = one short status only (running: PID; stopped: Not running; installed: Available / Not installed). **Controls** = labeled `Button`s `sm` only — **never** a status `Chip` in `__controls`, and **never** park the tool/CLI name on `label` when the install Button already names it. Failure detail → row **`InfoHint`**, not a sibling `FieldHint` essay (`tool：error…`). Failure mode: CONSUMER_TREATY CLI/tool probe name label + status Chip + FieldHint. Core ≥ **0.5.80** labeled-Button **8dp**. **At most one** `loading`. Click Start / Stop to toggle the sample.",
  "globals.rhythmActionEndHelp":
    "**Action cluster end-pack + label floor (hard ≥ 0.5.158 / **0.5.159** / **0.5.175** / CTA-under-start ≥ **0.5.205**):** `.fynns-control-cluster` defaults to trailing-edge pack. Label track floors at `--fynns-layout-control-row-label`. Long nowrap `.fynns-table-meta` in the cluster **shrinks + ellipsis** — never overflows left over the status label. Status on `label` (not a `Chip`). `controlsAlign=\"start\"` is for probe meta only — **never** for install / Configure Buttons (core ≥ **0.5.205** still end-packs labeled Buttons if `start` is misused). Failure modes: CONSUMER_TREATY left-packed Buttons; ControlRow label crushed to 2px; path meta paints over label. Live `#rhythm` end-align.",
  "globals.rhythmActionEndTitle": "Setup checks",
  "globals.rhythmActionEndReady": "Ready",
  "globals.rhythmActionEndPending": "Needs setup",
  "globals.rhythmActionEndMetaReadyTitle": "sample-tool (stream pull)",
  "globals.rhythmActionEndMetaReady":
    "version 2026.08.30 C:\\Users\\sample\\AppData\\Local\\Microsoft\\WinGet\\Packages\\sample.tool_8wekyb3d8bbwe\\sample-tool.exe",
  "globals.rhythmActionEndMetaPending":
    "prefs.json missing required keys - region, account, and sample-provider endpoint",
  "globals.rhythmActionEndConfigure": "Configure",
  "globals.rhythmActionEndRefresh": "Refresh checks",
  "globals.rhythmInstallCtaEndHelp":
    "**Install CTA never under `controlsAlign=\"start\"` (hard ≥ **0.5.205**):** service / CLI install rows use default end-pack (omit `start`) — `label` = short status, controls = labeled Button ± InfoHint. The anti-demo below **misuses** `start` on purpose; core still parks the install Button on the trailing edge. Do not invent consumer `margin-inline-start: auto`. Failure mode: CONSUMER_TREATY left-packed Buttons. Live `#rhythm` end-align.",
