  "globals.btnElevated": "Elevated",
  "globals.btnGhost": "Text",
  "globals.iconBtnTip": "Standard icon button",
  "globals.iconsHelp":
    "Full `@fynns/ui` icon library (`src/primitives/icons.tsx`). Consumers may use **any** glyph — not a curated subset. Missing meaning → add the SVG here + export + this catalog in the same change.",
  "globals.iconsBulkRecipeHelp":
    "Bulk toolbar recipe: exit mode → `CloseIcon` (not ArrowLeft); select all → `CheckSquareIcon` (not Check); deselect → `SquareIcon`; enter bulk → `ListChecksIcon` (not Clipboard). **Checked rows:** `Checkbox` only — never `active`/`selected` from `checked` (≥ 0.5.65).",
  "globals.iconsBulkRecipeAria": "Bulk toolbar icon recipe",
  "globals.iconsBulkExit": "Exit select mode",
