  "globals.iconsBulkDeselectAll": "Deselect all",
  "globals.iconsBulkEnter": "Enter bulk select",
  "globals.iconBtnFilled": "Filled icon button",
  "globals.iconBtnTonal": "Tonal icon button",
  "globals.iconBtnOutlined": "Outlined icon button",
  "globals.infoHintIconBody":
    "Standalone help: hover or focus the “i” for a short explanation. Prefer InfoHint over inventing an IconButton + Tooltip for pure information.",
  "globals.infoHintIconAria": "More about InfoHint",
  "globals.infoHintDangerBody":
    "Fail / error detail: use `tone=\"danger\"` on icon-only InfoHint beside a short `Fail` status so OK vs Fail rows scan at a glance.",
  "globals.infoHintDangerAria": "Fail detail help",
  "globals.infoHintLabeledTrigger": "What is this?",
  "globals.infoHintLabeledBody":
    "Labeled help: the plain text is the trigger (`cursor: help`, no underline / trailing “i”). Prefer for dense form or inspector rows.",
  "globals.infoHintLabeledAria": "What is this help",
  "globals.infoHintRowLabel": "Preview",
  "globals.infoHintRowSwitch": "Skip batch commands",
  "globals.infoHintRowBody":
    "Typical ControlRow preference pattern: InfoHint on the label; Switch alone in controls. Do not wrap tip+Switch in a wrapping cluster (narrow drawers stack tip above Switch — see `#sandbox-control-row-tip-switch-narrow`).",
  "globals.infoHintRowAria": "Preview mode help",
  "globals.infoHintNarrowLabel": "Sample preference",
  "globals.infoHintNarrowSwitch": "Hide sample catalog entries",
  "globals.infoHintNarrowBody": "Sample tip for a narrow ControlRow — keep the tip on the label, Switch alone in controls.",
  "globals.infoHintNarrowAria": "About sample preference",
  "globals.infoHintHelp":
    "`InfoHint` — informational affordance (M3: Tooltip on a help anchor). Icon-only uses the same 40dp ghost icon target and 16dp glyph as `IconButton md` (`cursor: help` — not an action). Pass `label` for a plain text trigger. Dense rows may use `size=\"sm\"`. **`tone=\"danger\"`** tints the “i” for Fail / error detail beside short `OK`/`Fail` status rows (probe strips — live `#rhythm`). Card / Collapsible `actions`: **≤1** InfoHint with a **short** tip — do not stack twin “i” icons or dump multi-topic essays (body FieldHint instead). The ControlRow + Switch + trailing i sample is InfoHint anatomy only — not a Dialog / Preferences row recipe (see Open Dialog with close). Preference how-to (≥ **0.5.292**): trailing InfoHint on the ControlRow label; track-only Switch in controls. Do not wrap tip+Switch in a wrapping cluster (narrow drawer stacks tip above Switch). Live `#sandbox-control-row-tip-switch-narrow`.",
  "globals.inputPlaceholder": "Input",
  "globals.inputAria": "Sample input",
  "globals.inputHelp":
    "Plain Input keeps text `capsule + field-pad` (**16dp**). When `leading` / `trailing` owns an edge (≥ **0.5.237**), that side drops to `--fynns-layout-capsule-chrome-pad-inline` (**4dp**) — SearchBar / NumberInput stepper flush. Do **not** invent consumer end pad / negative margin. Live contrast: this demo (plain + leading) vs `#password` (trailing eye). Failure: CONSUMER_TREATY Input trailing affix far from shell edge.",
  "globals.selectAria": "Sample select",
  "globals.selectLongOption": "sample-workspace-with-a-long-catalog-name",
  "globals.autocompleteAria": "Sample autocomplete",
  "globals.autocompletePlaceholder": "Filter colors…",
  "globals.autocompleteEmpty": "No matches",
  "globals.autocompleteDeprecatedAlert":
    "Deprecated (≥ 0.5.236): Autocomplete is kept for anatomy only — strongly discouraged. Prefer SearchBar (#search-bar) for type-to-filter, or CommandPalette for command pickers. Do not start new consumer screens on Autocomplete.",
  "globals.autocompleteHelp":
    "DEPRECATED anatomy (≥ **0.5.236**) — still live for chrome teaching, but **strongly discouraged**. Prefer **SearchBar** (`#search-bar`) or **CommandPalette**. Historical: M3 Autocomplete — click/type to open, filter, then pick; docked `.fynns-search-bar--expanded` joined capsule (Select uses portaled `.fynns-select-menu` ≥ **0.5.208**). Failure: CONSUMER_TREATY Select Autocomplete deprecated prefer Menu SearchBar.",
