    "Hover or ArrowRight on Sample volume for a nested menu (DropdownMenuSub). Live #sandbox-menu-submenu.",
  "globals.menuHelp":
    "M3 Menu (DropdownMenu): portaled surface with groups, separators, and checkbox items. Sort / filter rows with a leading kind glyph → `DropdownMenuCheckboxItem` **`icon`** prop (16dp `.fynns-menu-item-icon` — same band as plain `DropdownMenuItem`; label = text only). Check column + icon + label share one vertically centered row. Arrow keys move focus; Esc dismisses. Icon-only overflow → `iconOnly` ghost sm. **Labeled triggers** auto-append a trailing chevron that rotates open (≥ **0.5.253**; trailing flex slot + block icon ≥ **0.5.254**). **Leading glyph + label** → `leadingIcon` (16dp `.fynns-menu-trigger-leading`, vertically centered — ≥ **0.5.258**; live `#sandbox-menu-leading-icon`) — do **not** stuff `<>icon text</>` into `trigger` and hope baseline alignment works. **Form FieldBlock** hosts auto **matchTriggerWidth** (≥ **0.5.239** — menu width = live trigger; left flush with trigger ≥ **0.5.254**; long labels ellipsize; Select 0.5.238 parity). **Long catalogs** use capped `fynns-scroll` panel (`max-height: min(70dvh, 20rem)`) with a **visible** flyout overlay rail (≥ **0.5.251**) — `#sandbox-scroll-menu-stack`. Huge lists: filter / window in the consumer. Toolbar / `iconOnly` stay content-fit. Live `#sandbox-menu-field-match`.",
  "globals.menuFieldMatchLabel": "Sample discrete pick",
  "globals.menuFieldMatchAria": "Sample field menu",
  "globals.menuFieldMatchHelp":
    "FieldBlock + DropdownMenu (≥ **0.5.239** / ≥ **0.5.253** / ≥ **0.5.254** / ≥ **0.5.290**): portaled menu **width = live trigger** and **left flush**; labeled trigger keeps stadium Button chrome and a **trailing chevron**. A **Tooltip** (or bare span) around the Menu must still **fill the FieldBlock column** — tip hosts default inline-flex shrink-wrap; core stretches tip+span that wrap `.fynns-menu-root`. Prefer string trigger + OverflowTip and FieldHeader InfoHint for how-to. Failure: CONSUMER_TREATY DropdownMenu wider than FieldBlock trigger / FieldBlock Menu tip-wrap shrinks trigger / labeled DropdownMenu missing chevron / DropdownMenu panel left-shifted vs trigger / Menu chevron optically high.",
  "globals.menuFieldTipWrapLongLabel": "Sample long pick (tip-wrapped)",
  "globals.menuFieldTipWrapLongAria": "Sample tip-wrapped long field menu",
  "globals.menuFieldTipWrapShortLabel": "Sample short pick",
  "globals.menuFieldTipWrapShortAria": "Sample short field menu",
  "globals.menuFieldTipWrapHintAria": "About tip-wrapped field menus",
  "globals.menuFieldTipWrapHint": "How-to stays on InfoHint. Tip around Menu must not shrink the trigger vs a bare sibling.",
  "globals.menuFieldRefreshLabel": "Sample pick with refresh",
  "globals.menuFieldRefreshAria": "Sample field menu with refresh",
  "globals.menuFieldRefreshTip": "Refresh sample list",
  "globals.scrollMenuStackLabel": "Sample model",
  "globals.scrollMenuStackAria": "Sample model menu",
  "globals.scrollMenuStackFillerA":
    "Filler row A — keeps the capped host overflowing so the overlay Y rail is visible.",
  "globals.scrollMenuStackFillerB":
    "Filler row B — open the menu: page rails stay under the flyout; the menu’s own thumb stays visible.",
  "globals.scrollMenuStackFillerC":
    "Filler row C — page rails use --fynns-z-scroll-overlay; menu rails use --fynns-z-scroll-overlay-flyout.",
  "globals.scrollMenuStackFillerD":
    "Filler row D — Snackbar/toast still sits above menus.",
  "globals.scrollMenuStackHelp":
    "**Menu scroll thumbs (≥ 0.5.251):** page `.fynns-scroll-overlay-portal` stays at `--fynns-z-scroll-overlay` (below modal-flyout). **Flyout hosts** (`.fynns-menu` / Select list) paint rails in a second portal at `--fynns-z-scroll-overlay-flyout` so the panel’s own thumb is visible while scrolling. Open this long DropdownMenu — hover/scroll and confirm the Y thumb on the menu edge. Failure: CONSUMER_TREATY Menu/Select flyout scroll thumb buried under panel. Live `#sandbox-scroll-menu-stack`.",
