  "globals.chatComposerModelEmptyTrigger": "No model",
  "globals.chatComposerModelSectionsHelp": "Recipe (≥ 0.5.291): ChatComposer model Menu uses DropdownMenuGroup sections Local / Cloud / CLI with separators. Only include a section when that source is configured (API key, local endpoint, CLI auth file). Empty sections stay out of the menu. If none are configured, show a disabled “No models available” row. Live #sandbox-chat-composer-model-sections / #sandbox-chat-composer-model-empty.",
  "globals.chatSend": "Send",
  "globals.chatStop": "Stop generating",
  "globals.chatScrollBottom": "Scroll to bottom",
  "globals.shellChatEcho": "Echo: {msg}",
  "globals.chatHelp":
    "**Chat** shell (`Chat` + `ChatThread` + `ChatComposer` + `ChatScrollToBottom`) + **ChatMessage** / **ChatMarkdown**. Empty thread: slim `EmptyState` + full-width clickable `Surface` `variant=\"soft\"` in `empty` (message-bar width; wrap; app owns rotate with vertical silk slide via `--fynns-duration-slow` / `--fynns-ease-emphasized`, or instant under reduced-motion; send). Do **not** use Chip or revived `ChatStarterPrompts`. Dual placement: **main** = 48rem host (`--fynns-layout-chat-max-width`), user bubble **70%**; **aside** (EndAside / `.fynns-chat-host--fill`) = 100% pane, user bubble ceiling **100%** so long turns share the composer shell edges (short shrinks; `radius-22`; composer `radius-3xl`; `--fynns-color-chat-user-bubble`); composer **100%**. Thread pad + composer inset share dialog-inset (composer aliases thread token) so bubble end and composer shell end align (equal L/R). Soft floor `min(--fynns-layout-chat-min-width, 100%)` — no window lock. `system` = centered muted notice. Stick-to-bottom + scroll FAB. Enter sends / Shift+Enter newline → expanded bottom toolbar (leading start, Send end); **CJK IME Enter while composing confirms only (does not send)** — ChatGPT parity. Multiline layout: `llm/CHAT_COMPOSER_LAYOUT.md`. Prefer `ChatMessage markdown` / `<ChatMarkdown>` for LLM turns (L2 GFM subset: fenced → `CodeBlock`, plain ul/ol, inline pills). Direct body siblings use `--fynns-chatmessage-body-stack-gap` (aliases `unit-stack-gap`). `streaming` = caret only. `thinking` / `ChatThinking` = reasoning disclosure above the answer. `error` + `onRetry` = ChatGPT failed-generation footer (danger copy + Regenerate). `actions` = Copy + Regenerate + More `IconButton`/`DropdownMenu` (hover reveal; **consumer wires LLM rerun** — sandbox snackbar is demo only). `citations` = browsing source chips under assistant turns (hover preview; click opens; +N expands footnote cards).",
  "globals.chatCitationsAnatomyHelp":
    "Direct imports: inline `ChatCitationChip` + standalone `ChatCitations` (not only via `ChatMessage.citations`). Same publisher-first chip + footnote expand.",
  "globals.thinkingStreaming": "Thinking",
  "globals.thinkingLabel": "Thinking",
  "globals.thinkingDuration": "Thought for {n}s",
  "globals.thinkingActionThink": "Thinking",
  "globals.thinkingActionSearch": "Calling the catalog search…",
  "globals.thinkingActionRead": "Reading sample docs…",
  "globals.thinkingActionCheck": "Executing layout checks…",
  "globals.thinkingActionDraft": "Drafting a reply…",
  "globals.thinkingActionsHelp":
    "Dummy agent / LLM activity labels (streaming). Use progressive *-ing* copy (`Calling…`, `Searching…`); done → past (`Thought for Ns`). Label shimmer; swap `streamingLabel` to morph. Multi-step trees → **ChatActivity** (AGENTS.md Label tense).",
  "globals.thinkingBody":
    "Checked naming against CHATMESSAGE_TOKENS and kept the disclosure off the Collapsible card shell.",
  "globals.thinkingAnswer":
    "Use ChatThinking via ChatMessage.thinking — summary only; the app owns any markdown.",
  "globals.thinkingSimulate": "Simulate agent run",
  "globals.thinkingReset": "Reset done",
  "globals.thinkingHelp":
    "**ChatThinking** — Wave 1 single-block reasoning / agent-activity disclosure (ChatGPT / Claude “Thinking / Thought for Ns”; Cursor-style tool status via `streamingLabel`). **Label tense (consumer):** streaming / activity = progressive (*Thinking*, *Calling the function…*, *Reading sample docs…*); done = past (*Thought for Ns*). Core does not rewrite copy — swap strings when streaming ends. Slot via `ChatMessage.thinking` between name and bubble. Streaming: force-open unless the user pinned closed (trigger stays enabled so it can collapse mid-run; a new run clears the pin) + label shimmer; remount on label change for swap enter. Done: auto-collapse once; user expand sticks. No children → static duration strip (no chevron). No default streaming orb — pass `icon` only for a custom leading glyph. No markdown / LLM in core; do not live-region thought tokens. Geometry: `CHATMESSAGE_TOKENS` `thinking-*`. Multi-step tool / status tree → **ChatActivity** (Wave 2).",
  "globals.activityHeaderStart": "Gathering context…",
  "globals.activityHeaderMemory": "Created memory file",
  "globals.activityHeaderPlan": "Updated plan with details",
  "globals.activityHeaderDone": "Updated plan with details",
  "globals.activityStepGather": "Gathering context…",
  "globals.activityStepGatherDesc":
    "Scanning the open catalog and layout tokens before drafting a plan.",
  "globals.activityStepCreate": "Created memory file",
  "globals.activityStepUpdate": "Updated memory file",
  "globals.activityStepRead": "Reading the plan…",
  "globals.activityStepReadDesc":
    "Checking the draft outline against the sandbox form recipe.",
  "globals.activityStepPresent": "Presenting the plan…",
  "globals.activityStepPresentDone": "Presented plan",
  "globals.activityStepPresentDescBefore":
    "I’ve refined the outline and am preparing to ask clarifying questions via ",
  "globals.activityStepPresentCode": "sandbox_askQuestions",
  "globals.activityStepPresentDescAfter": ".",
