    "Editable body / file well lives in this Card. Copy / Discard / Save IconButtons sit in Card `actions` — never a lone end-align strip under PageScroll with no Card title.",
  "globals.cardDraftHelp":
    "Draft chrome (copy / discard / save / view-diff): **Card `actions`** of the Card that owns the editable subject (`chrome=\"plain\"` when nesting CodeBlock). CatalogMorph heads use `size=\"sm\"`. **Forbidden:** bare `.fynns-control-cluster--end-align` or `ControlRow` of save/discard IconButtons as a PageScroll / unit-stack sibling outside any Card — reads as floating chrome with unclear scope. Live: `#sandbox-card-draft-actions`.",
