  "globals.cardChromeIconHelp":
    "**Self-evident Card chrome (hard ≥ 0.5.173):** copy / save-defaults / open-folder in Card `actions` or densified Select clusters = **`IconButton` + `Tooltip`** (`ClipboardIcon` / `SaveIcon` / `FolderOpenIcon`) — not labeled ghost `Button` text (**information redundancy** beside sibling icon disks). Keep labeled Buttons for primary workflow verbs (`Validate` / `Deliver`). Failure: CONSUMER_TREATY Card chrome labeled ghost Copy/Save instead of IconButton+Tooltip. Live `#sandbox-card-chrome-icon-actions`.",
  "globals.providerSettingsTitle": "Sample providers",
  "globals.providerSettingsScopeTip":
    "Manage surface: pick a provider, connect credentials when needed, choose a model from a Menu. Runtime composer pickers stay out of this Card.",
  "globals.providerSettingsHelp":
    "**Credentialed provider Manage (hard ≥ 0.5.267 / same-row Save ≥ **0.5.268** / model Menu ≥ **0.5.269** / Save `ghost` `sm` ≥ **0.5.271**):** preference `ControlRow` for active provider → **when needed** password `FieldBlock` (eye in `trailing`) + **same-row** `.fynns-control-cluster--end-align` — `Input` `fynns-control-cluster__grow` **then** `SaveIcon` IconButton `ghost` `sm` (never tonal/md; never `unit-stack` under the field) → model `FieldBlock` + `DropdownMenu` `__grow` + refresh sm (**not** a selectable model `List` wall; prefer Menu over soft-deprecated `Select`) → fail = `InlineAlert` (success silent) → one Verify. Do **not** replace the key field with connection chips / Add Dialog, nor paint every-provider OK/Fail walls. Failure: CONSUMER_TREATY provider Manage flat dump; FieldBlock Save IconButton wraps under Input. Live `#provider-settings`.",
