  "globals.pageScrollListAria": "页滚目录样例",
  "globals.splitPaneHelp":
    "内容区内可拖分栏（编辑器 | 预览、列表 | 详情）。不是 EndAside / 抽屉壳层 — 那些管 destination / 检查器轨。拖动手柄或聚焦后用方向键；实时尺寸为 `--fynns-split-size`。宿主需定高（舞台 / FillColumn 子级）。",
