  "globals.fullscreenFlushOpen": "打开全屏（CodeBlock 顶天）",
  "globals.fullscreenFlushTitle": "项目笔记",
  "globals.fullscreenFlushFile": "notes.xml",
  "globals.fullscreenFlushHelp":
    "Flush-start：FullscreenDialog 正文第一个子项是 keep-set 带边框井（CodeBlock / Surface / 表包装）时，core 去掉 padding-block-start，井框贴在标题下——不要 18dp 空带。标题 chrome 仍 content-inset。允许一层无垫 fill 宿主。不是 Card chrome=\"plain\" 贴边。权威：AGENTS.md Flush-start overlay body。",
  "globals.drawerNestedScrollOpen": "打开抽屉嵌套滚动",
  "globals.drawerNestedScrollTitle": "示例配置",
  "globals.drawerNestedScrollProvider": "提供商",
  "globals.drawerNestedScrollRegion": "区域",
  "globals.drawerNestedScrollDigest": "摘要",
  "globals.drawerNestedScrollCard": "已挂载示例卡片",
  "globals.drawerNestedScrollHelp":
    "Drawer 正文滚动 + 嵌套 CodeBlock：overlay Y 轨道裁剪在 TopAppBar、`.fynns-dialog-head` 与分区标题下方，外层滚动时拇指不会画在更高 chrome 上。页轨经 `--fynns-z-scroll-overlay` 低于菜单；菜单/Select 自身拇指用 `--fynns-z-scroll-overlay-flyout`（≥ **0.5.251** — 对照 `#sandbox-scroll-menu-stack`）。活样例 `#drawer-nested-scroll`。",
  "globals.dialogNestedScrollOpen": "打开对话框嵌套滚动",
  "globals.dialogNestedScrollTitle": "示例嵌套滚动",
  "globals.dialogNestedScrollFold": "已挂载示例正文",
  "globals.dialogNestedScrollHelp":
    "居中 Dialog + List + Collapsible + plain CodeBlock：`maxHeight` 写到根上的 `--fynns-code-block-max-height`；copy-float 的 overlay Y 轨先做圆角裁剪再做 chrome 裁剪，拇指不超出 `radius-3xl`、不越过面板底边。活样例 `#dialog-nested-scroll`。",
  "globals.dialogViewportOpen": "打开视口工作区对话框",
  "globals.dialogViewportTitle": "示例配置工作区",
  "globals.dialogViewportDescription": "在不离开当前页面的情况下编辑较大配置。",
  "globals.dialogViewportHelp":
    "大型非全屏工作区：`Dialog size=\"viewport\"` 保留居中圆角和视口留白，同时提供更宽、更高的工作面。直属 editable CodeBlock 使用 `autoGrow={false}` 后会填满正文剩余高度，无需消费侧 CSS。活样例 `#dialog-viewport`。",
  "globals.overlayHelp":
    "对话框：M3 basic（`Dialog` / `ConfirmDialog`，radius-3xl，默认无 X）、大型内嵌工作区（`Dialog size=\"viewport\"`）与 full-screen（`FullscreenDialog`）。正文首个带边框井（CodeBlock）在全屏标题下顶天贴合 — `#fullscreen-flush`。可关闭的标签行 = `Dialog` + `showCloseButton` + 全宽 ControlStack（Switch 与 X 共 end 缘）。另有 Drawer / BottomSheet / DialogShell。目的地用 NavigationDrawer。",
  "globals.dialogOpen": "打开对话框",
  "globals.dialogLabeledOpen": "打开 Dialog（关闭）",
  "globals.dialogLabeledTitle": "带关闭的 Dialog",
  "globals.dialogLabeledHelp":
    "可关闭 Dialog + ControlStack（不是 Settings/Preferences 专用壳）：Dialog sm + showCloseButton + ControlStack columns={1}。每行一个可见名 = ControlRow label；Switch 仅轨道（label=\"\" + ariaLabel）。禁止把 InfoHint demo（带文案的 Switch + 尾随 i）抄进 Dialog 行。Switch 轨道与 CloseIcon 字形右缘对齐（不是 40dp 热区）。",
  "globals.dialogLabeledOptA": "选项 A",
  "globals.dialogLabeledOptB": "选项 B",
  "globals.dialogLabeledOptC": "选项 C",
  "globals.dialogShellOpen": "打开 DialogShell",
  "globals.dialogShellTitle": "自定义壳",
  "globals.dialogShellBody":
    "底层 DialogShell — 自行提供头/身。Esc 与遮罩仍可关闭。",
  "globals.dialogShellClose": "关闭壳",
  "globals.dialogTitle": "居中对话框",
  "globals.dialogDescription": "新建示例分组。",
  "globals.dialogCreateHelp": "标题下 description 仅短 caption。方向 / 路径 / 覆盖说明放在 headActions 的 InfoHint sm — 禁止多行 how-to 挂标题下（≥ 0.5.284）。",
  "globals.dialogBody": "适合短表单，不必占满视口。",
  "globals.dialogCreateNameLabel": "显示名称",
  "globals.dialogCreateNamePlaceholder": "示例分组",
  "globals.dialogCreateAction": "创建",
  "globals.dialogCreateCancel": "取消",
  "globals.dialogFootCanonicalHelp": "居中 Dialog 表单脚栏 — **唯一**样式（≥ **0.5.286**）：`.fynns-control-cluster--end-align` + labeled Button（Cancel ghost 左 → primary 确认右）。禁止：Dialog 正文里 primary IconButton / 对勾盘 / Fab。说明进 headActions InfoHint；勿用 description 复述 FieldBlock 标签。",
  "globals.dialogTitleBodyInsetHelp": "居中 Dialog（无 Confirm 脚栏）：标题顶距 = content-inset（18dp），与 body 底 / 尾部主 IconButton 下距齐（≥ 0.5.280）。勿改 .fynns-dialog-head 或半 dialog-inset。",
  "globals.dialogClose": "关闭",
  "globals.nestedDialogOpen": "打开嵌套对话框",
  "globals.nestedDialogTitle": "嵌套表单",
  "globals.nestedDialogDescription":
    "与页内样例相同的 outlined Card 分区 — Dialog 只是可选宿主之一。",
  "globals.nestedDialogFieldLabel": "长文本",
  "globals.nestedDialogExpandTip": "在大编辑器中打开",
  "globals.nestedDialogResetTip": "恢复默认",
  "globals.nestedSectionHelp":
    "嵌套分区配方（宿主无关）：Card（静态头 + 正文）+ FieldBlock + 满宽 Textarea。可放在页面、Dialog、Drawer 等 — 由 agent 自选宿主。无标题的井用 Surface。",
  "globals.surfaceHelp":
    "`Surface` — 通用描边 / 色调井，可包任意子节点（表单、iframe、BusyRegion）。变体：`outlined` / `filled` / `elevated` / `soft`（surface-2，与 Banner default 同色）。默认无内边距；`padded` = 四边等距 `--fynns-layout-content-inset`（勿 rem/`px` 或块/行向混用）。`interactive` = M3 state-layer hover/press（大按钮语法；可包在父级 `button` 下）。需要静态 title / icon / actions 头时用 Card。空线程示例 prompt：在 `ChatThread.empty` 用满宽 soft `Surface` `padded` `interactive`（对照 `#chat`）。",
  "globals.fieldHeaderLabel": "裸 FieldHeader",
  "globals.fieldHeaderPlaceholder": "FieldHeader 下的控件",
  "globals.fieldHeaderReveal": "显示内容",
  "globals.fieldHeaderHelp":
    "`FieldHeader` 仅解剖（控件上方标签行）。字段内 trailing IconButton 保持 **sm**（32dp）— 对照 `#sandbox-field-header-api-key`。设置 / 凭证 / env / Select+刷新 / OK·Fail 探测墙 → `#form-recipe` / `#provider-settings` / `#env-check` / `#info-hint` — **禁止**在本 slug 复活 Manage 大 Card。对照 `#field-header`。",
  "globals.surfaceFieldPlaceholder": "井内任意控件",
