  "globals.surfacePreviewLabel": "预览井",
  "globals.nestedDialogHelp":
    "可选：把同一 Card + FieldBlock 配方放进 Dialog（嵌套并不要求 Dialog）。",
  "globals.confirmOpen": "打开确认框",
