  "globals.drawerDescription": "模态侧栏 — 背后页面被遮挡。",
  "globals.drawerBody": "内容检查器用 Drawer；目的地导航用 NavigationDrawer。",
  "globals.textareaPlaceholder": "输入多行提示词…",
