  "globals.rhythmSurfaceHelp":
    "带 pad 的 Surface + 单行 ControlBlock：说明留在名称列；ToggleGroup / 操作簇对名称+说明纵向居中 — 即使这一列偏窄。**禁止**再放一条只复述 ToggleGroup 选项名的兄弟 FieldHint（信息冗余 — 失败模式：CONSUMER_TREATY FieldHint restates ToggleGroup / Tabs labels）。",
  "globals.rhythmCatalogHelp":
    "**目录列表顶栏（硬 ≥ 0.5.266）：** 独立 `ControlRow`（不在 `ControlStack` 内）填满宿主 — 标签 `1fr`，IconButton 放进一个 `.fynns-control-cluster` 贴尾（**md** 默认 — 与同页 List trailing 一致）。**禁止**在 Plus / 导入 / 清空旁塞裸 `{n}` / `.length` 的 `.fynns-table-meta`，**禁止**把 `(N)` / `N/M` 写进标签 — List / EmptyState 已表达条数（**信息冗余**；CONSUMER_TREATY ControlRow unsolicited item count）。仅当产品明确要计数时才显示。不要留内容宽小岛、按钮停在标签旁。",
  "globals.rhythmCatalogLabel": "服务器",
  "globals.rhythmCatalogBulk": "批量选择",
  "globals.rhythmCatalogRefresh": "刷新列表",
  "globals.rhythmCatalogAdd": "新增服务器",
  "globals.rhythmEndAlignHelp":
    "无可见名称的动作脚栏：一个 `.fynns-control-cluster--end-align`（`justify-content: flex-end` — 纯 IconButton 条不需要 `__grow`）。仅当左侧 Select / meta 要吃剩余宽度时才加 `__grow`。禁止 `ControlRow` `label=\"\"`（空标签列 / 按钮漂中左）。**Busy（硬）：** 点任一按钮 — **最多一颗** `loading` 圈；兄弟只 `disabled`、不画第二圈。禁止 `loading={busy}` 绑到每一颗。",
  "globals.rhythmEndAlignIconHelp":
    "纯 IconButton 贴尾条：Tooltip → IconButton 保持 40dp 正圆（不要在通栏 flex 行上被压成细椭圆）。",
  "globals.rhythmEndAlignIconOpenTip": "打开目标文件夹",
  "globals.rhythmEndAlignIconPrimaryTip": "开始拷贝归档",
  "globals.rhythmEndAlignSecondary": "次要",
  "globals.rhythmEndAlignPrimary": "主要操作",
  "globals.rhythmServiceHelp":
    "**服务 / 进程 / CLI 探测（硬）：** `ControlRow` `label` 仅短状态（运行：PID；停止：未运行；安装：可用 / 未安装）。**控件列** 仅 labeled `Button` `sm` — **禁止** cluster 内状态 `Chip`，也**禁止**在安装 Button 已点名工具时把工具名再当 `label`。失败详情 → 行内 **`InfoHint`**，勿兄弟 `FieldHint` 长文（`tool：error…`）。失败模式：CONSUMER_TREATY CLI/tool probe name label + status Chip + FieldHint。Core ≥ **0.5.80** 带文案 Button **8dp**。同一 cluster **最多一颗** `loading`。点启动 / 停止切换样例。",
  "globals.rhythmActionEndHelp":
    "**动作簇右齐 + label 地板（硬 ≥ 0.5.158 / **0.5.159** / **0.5.175** / CTA 误用 start ≥ **0.5.205**）：** `.fynns-control-cluster` 默认贴尾缘。label 轨地板 `--fynns-layout-control-row-label`。簇内长 nowrap `.fynns-table-meta` **收缩 + 省略** — 禁止向左溢出盖住状态 label。状态在 `label`（勿 `Chip`）。`controlsAlign=\"start\"` 仅探测 meta — **禁止**给安装 / 配置 Button 加 `start`（≥ **0.5.205** 误加仍会右齐）。失败模式：CONSUMER_TREATY left-packed Buttons；ControlRow label crushed to 2px；path meta paints over label。对照 `#rhythm` end-align。",
  "globals.rhythmActionEndTitle": "环境检查",
