  "globals.rhythmInstallCtaEndHelp":
    "**安装 CTA 禁止 `controlsAlign=\"start\"`（硬 ≥ **0.5.205**）：** 服务 / CLI 安装行用默认右齐（省略 `start`）— `label` = 短状态，控件 = labeled Button ± InfoHint。下方反例故意误用 `start`；core 仍把安装 Button 贴尾缘。勿 invent 消费仓 `margin-inline-start: auto`。失败模式：CONSUMER_TREATY left-packed Buttons。对照 `#rhythm` end-align。",
