    "完整 `@fynns/ui` 图标库（`src/primitives/icons.tsx`）。消费仓可用**任意**字形 — 不是精选白名单。缺语义 → 在同一次改动里加 SVG + 导出 + 本目录。",
  "globals.iconsBulkRecipeHelp":
    "批量工具条：退出模式 → `CloseIcon`（不要 ArrowLeft）；全选 → `CheckSquareIcon`（不要 Check）；取消全选 → `SquareIcon`；进入批量 → `ListChecksIcon`（不要 Clipboard）。**勾选行：** 仅 `Checkbox` — 禁止用 `checked` 驱动 `active`/`selected`（≥ 0.5.65）。",
