  "globals.infoHintIconBody":
    "独立帮助：悬停或聚焦 “i” 查看简短说明。纯信息请用 InfoHint，不要手写 IconButton + Tooltip。",
  "globals.infoHintIconAria": "关于 InfoHint 的更多说明",
  "globals.infoHintDangerBody":
    "Fail / 错误详情：短 `Fail` 状态旁的 icon-only InfoHint 使用 `tone=\"danger\"`，便于一眼区分 OK 与 Fail。",
  "globals.infoHintDangerAria": "失败详情帮助",
  "globals.infoHintLabeledTrigger": "这是什么？",
  "globals.infoHintLabeledBody":
    "标签型帮助：纯文字为触发器（`cursor: help`，无下划线 / 无尾随 “i”）。适合密排表单或 inspector 行。",
  "globals.infoHintLabeledAria": "这是什么的帮助",
  "globals.infoHintRowLabel": "预览",
  "globals.infoHintRowSwitch": "跳过批处理命令",
  "globals.infoHintRowBody":
    "常见 ControlRow 偏好写法：InfoHint 挂在标签尾；Switch 单独在右侧。禁止 tip+Switch 进会 wrap 的 cluster（窄抽屉会竖叠 — 见 `#sandbox-control-row-tip-switch-narrow`）。",
  "globals.infoHintRowAria": "预览模式帮助",
  "globals.infoHintNarrowLabel": "示例偏好",
  "globals.infoHintNarrowSwitch": "隐藏示例目录条目",
  "globals.infoHintNarrowBody": "窄 ControlRow 样例说明 — tip 挂在标签尾，Switch 单独在右侧。",
  "globals.infoHintNarrowAria": "关于示例偏好",
  "globals.infoHintHelp":
    "`InfoHint` — 信息型帮助（M3：Tooltip 锚在帮助触发器上）。无可见名称时与 `IconButton md` 同 40dp 圆形热区 + 16dp 字标（`cursor: help`，非动作按钮）；传 `label` 则为纯文字触发。密排行可用 `size=\"sm\"`。**`tone=\"danger\"`** 将 “i” 染红，用于短 `OK`/`Fail` 状态行旁的 Fail / 错误详情（探测条 — 见 `#rhythm`）。Card / Collapsible `actions`：**最多一个** InfoHint，且 tip **要短** — 禁止并排两个「i」、禁止气泡堆多主题长文（改放正文 FieldHint）。下方 ControlRow + Switch + 尾随 i 只演示 InfoHint 解剖，不是 Dialog / Preferences 行配方（见「打开 Dialog（关闭）」）。 偏好说明（≥ **0.5.292**）：ControlRow `label` 尾挂 InfoHint；`__controls` 仅轨道 Switch。禁止 tip+Switch 进会 wrap 的 cluster（窄抽屉会竖叠）。对照 `#sandbox-control-row-tip-switch-narrow`。",
  "globals.inputPlaceholder": "输入框",
  "globals.inputAria": "示例输入",
  "globals.inputHelp":
    "无 affix 的 Input 保持文案 `capsule + field-pad`（**16dp**）。当 `leading` / `trailing` 占用一边（≥ **0.5.237**），该侧收成 `--fynns-layout-capsule-chrome-pad-inline`（**4dp**）— 与 SearchBar / NumberInput 步进器同 flush。**禁止**消费侧自造 end pad / 负 margin。活对照：本样例（plain + leading）与 `#password`（trailing 眼睛）。失败模式：CONSUMER_TREATY Input trailing affix far from shell edge。",
  "globals.selectAria": "示例选择",
