  "globals.navDrawerModeTrailingHelp":
    "行尾：未悬停隐藏；悬停慢速渐显。优先「更多 (…)」——删除进菜单（danger）。活示例：仅 More / 重命名+More / 置顶+重命名+More。",
  "globals.navDrawerSessionAria": "示例会话侧栏",
