  "globals.navDrawerModeHideBuiltinHint":
    "开启后不显示只读内置条目（示例政策说明 — 用 InfoHint，不要用 ControlBlock description）。",
  "globals.navDrawerModeHideBuiltinHintAria": "关于隐藏示例条目",
