  "globals.toolbarHelp":
    "M3 Expressive Toolbar：停靠全宽条或浮动胶囊（`standard` / `vibrant`）。带标签的检查器行请优先用 ControlStack。",
  "globals.searchBarAria": "搜索资料库",
