  "globals.chatAssistantStackNote":
    "裸字符串与 CodeBlock 兄弟会吃到 `--fynns-chatmessage-body-stack-gap`（16dp / unit-stack-gap）— ChatMessage 会把裸文本包成 `.fynns-chat-message-prose`；不要在消费仓用本地 CSS 补这个间距。",
