  "globals.chatComposerThinkingToggleNarrowHelp": "配方（≥ 0.5.293）：~365px 窄壳 — 同一 endActions 配方；core ≤36rem 隐藏 pill 文案（仅图标；Tooltip + aria-label；禁止中宽截成 “T.”）。活样 #sandbox-chat-composer-thinking-toggle-narrow。",
