  "globals.listStatic": "偏好设置",
  "globals.listStaticSupporting": "静态行（无 onClick）",
  "globals.listHelp":
    "M3 内容列表 List / ListItem（1–3 行）。选中/悬停 = host 上一块 radius-3xl pill（secondary-container，与 NavigationDrawerItem 一致）。ListItem 之间不要 Divider — `--fynns-list-item-gap`（4dp）+ pill。种类不要左边竖标/inset 轨 — leading 图标 + trailingSupportingText。图标→文案 `--fynns-list-gap`（16dp）；三行栈 `--fynns-list-content-gap-3`（8dp）。装饰 chevron 并入主行点击；IconButton trailing 仍是兄弟，但点亮同一 host wash。路径目录 = 一个 List 多行 ListItem — 禁止每条外包加垫 Surface/Card。长 Card / PageScroll List（≥ **0.5.145**）：`useRevealMore` 用 **5** / 每次 **5**（`REVEAL_MORE_LIST_DEFAULT_*`）+ `RevealMore` 放在 List 后 — 见 `#list` 渐进样例。见 AGENTS.md Content density。",
  "globals.listRevealCaption": "示例列表（渐进披露）",
  "globals.listRevealAria": "示例目录条目",
  "globals.listRevealHint":
    "这些条目尚未匹配。请映射到目录 id，或标记为本机/免费。",
  "globals.listRevealMap": "映射",
  "globals.listRevealMapSnack": "映射操作（示例）",
  "globals.listRevealMore": "更多",
  "globals.listRevealContinue": "继续",
  "globals.listRevealContinueSnack": "继续操作（示例）",
  "globals.listRevealHelp":
    "Card / PageScroll 内长 List（≥ **0.5.145**）：`useRevealMore`（**5** / 每次 **5**）+ `RevealMore` 放在 List **后**（unit-stack 兄弟）。core 在脚上下各增加 16dp 净空，再叠加容器间距：此处 List→更多及更多→后续 CTA 均为 32dp；Drawer Item 的 4dp 行距叠加后为 20dp，见聊天产品布局。行由 app `slice`；文案本地化（`更多` / `Show more`）；不加消费侧间距 wrapper。短列表 / Dialog / 真 `Pagination` 豁免。见下方样例。",
  "globals.listHostToneHelp":
    "目录种类 = leading 图标 + trailingSupportingText（或 .fynns-table-meta）。不要左边竖标、inset 轨或额外 host 洗底——选中只靠 radius-3xl pill。禁止用 div 包 ListItem。headline 用 UI 字族（勿 mono）。",
  "globals.listHostToneAria": "用图标和尾部文案表达种类的列表示例",
  "globals.listHostToneAccent": "项目默认",
  "globals.listHostToneAccentSupporting": "随包文件夹——种类是字形，不是色条",
  "globals.listHostToneAccentMeta": "内置",
  "globals.listHostToneMuted": "示例配置",
  "globals.listHostToneMutedSupporting": "只读文件——尾部文案，不是弱化竖条",
  "globals.listHostToneMutedMeta": "只读",
  "globals.listHostTonePlain": "工作区偏好",
  "globals.listHostTonePlainSupporting": "应用自有行——与邻行同一宿主",
  "globals.listHostTonePlainMeta": "自定义",
  "globals.listOrgDatesHelp":
    "标题 + 组织 + 日期区间 — **组织名留在标题下**，日期放 **`trailingSupportingText`**。日期目录传 **`List` `trailingMetaAlign=\"start\"`**（**固定** meta 列；盒与墨迹**左齐** ≥ 0.5.13；固定列宽 ≥ **0.5.223** — 非内容宽右贴）。状态 / kind → **`overline`** — **禁止**把 `已完成, 2025-10 - 2026-03` 粘进 trailing。**禁止**把 `组织 · 2025-10 – 2026-03` 粘进 `supportingText`。区间用 ASCII 连字符（`2025-10 - 2026-03`）— 可见 chrome **不要** `·` / `–` / `—`。见 AGENTS.md Language **UI punctuation**。",
  "globals.listOrgDatesAria": "组织与日期区间列表示例",
