  "globals.cardPlainAlignOptionB": "选项 B",
  "globals.cardPlainAlignHelp":
    "**FieldHeader 左缘/顶缘对齐（硬 ≥ 0.5.114）：** 默认 `chrome=\"card\"` 与 `chrome=\"plain\"` 正文 pad 均为 `--fynns-layout-content-inset`（18dp，**四边**含 block-start）— 标签共用同一盒。Plain 兄弟 gap 仍为 `nest-gap`。测量 `#sandbox-card-plain-field-align`。",
  "globals.cardHintAria": "导出包说明",
  "globals.cardHintTip": "仅打包受管配置；大体量本机库请用下方归档。",
  "globals.cardHintBodyLead":
    "更长的纳入 / 排除说明放正文（FieldHint），不要再叠第二个标题「i」。",
  "globals.cardHintBodyMeta": "sample-org / sample-repo / long-branch-name-that-should-ellipsis-in-narrow-card",
  "globals.cardActionsStripTitle": "sample-entry/CONFIG.md",
  "globals.cardActionsStripBody":
    "标题操作区保持一条横向 .fynns-control-cluster（扁平 IconButton + 最多一个 InfoHint）。Lead 偏好约 40% 但会让位，窄宿主上尾部危险盘仍完整可见（≥ 0.5.57）。禁止把 ToggleGroup 塞进标题栏 — 见正文模式样例。同一条带内所有图标 chrome 共用 size md（40dp hover）。",
  "globals.cardActionsStripHint": "标题只放短 tip — 细节留在正文。",
  "globals.cardActionsStripHintAria": "条目操作说明",
  "globals.cardActionsStripStar": "收藏",
  "globals.cardActionsStripPin": "置顶",
  "globals.cardActionsStripOpen": "打开文件",
  "globals.cardActionsStripFolder": "打开所在文件夹",
  "globals.cardActionsStripDelete": "删除",
  "globals.cardDraftTitle": "示例条目正文",
  "globals.cardDraftDiscard": "撤回未保存（从磁盘重新加载）",
  "globals.cardDraftSave": "保存",
  "globals.cardDraftCopy": "复制正文",
  "globals.cardDraftBody":
    "可编辑正文 / 文件井在本 Card 内。复制 / 撤回 / 保存 IconButton 放在 Card `actions` — 禁止在 PageScroll 下单独挂一条无 Card 标题的 end-align 条。",
  "globals.cardDraftHelp":
    "草稿 chrome（复制 / 撤回 / 保存 / 查看改动）：放在**拥有可编辑主体**的 Card 的 **`actions`**（嵌套 CodeBlock 时 `chrome=\"plain\"`）。CatalogMorph 标题栏用 `size=\"sm\"`。**禁止：** 在 PageScroll / unit-stack 里用裸 `.fynns-control-cluster--end-align` 或 `ControlRow` 挂保存/撤回 IconButton 且不属于任何 Card — 读成悬浮 chrome、作用域不明。对照：`#sandbox-card-draft-actions`。",
  "globals.cardChromeIconTitle": "示例架构图",
  "globals.cardChromeIconCopy": "复制 prompt",
  "globals.cardChromeIconFolder": "打开输出文件夹",
  "globals.cardChromeIconSaveDefaults": "保存默认",
  "globals.cardChromeIconTypeAria": "图类型",
  "globals.cardChromeIconTypeFlat": "平面",
  "globals.cardChromeIconTypeTree": "树形",
  "globals.cardChromeIconQualityAria": "质量",
  "globals.cardChromeIconQualityFast": "快速",
  "globals.cardChromeIconQualityHigh": "高质量",
  "globals.cardChromeIconHelp":
    "**自明 Card chrome（硬 ≥ 0.5.173）：** Card `actions` 或 densified Select 旁簇里的复制 / 保存默认 / 开文件夹 = **`IconButton` + `Tooltip`**（`ClipboardIcon` / `SaveIcon` / `FolderOpenIcon`）— 禁止 labeled ghost「复制 Prompt」「保存默认」（与旁侧图标盘 **信息冗余**）。主流程动词 CTA（Validate / Deliver）仍可用 labeled Button。失败：CONSUMER_TREATY Card chrome labeled ghost Copy/Save instead of IconButton+Tooltip。对照 `#sandbox-card-chrome-icon-actions`。",
  "globals.providerSettingsTitle": "示例提供商",
  "globals.providerSettingsScopeTip":
    "Manage 面：选择提供商、需要时连接凭据、用下拉选择模型。运行时作曲器旁的 picker 不在此 Card。",
  "globals.providerSettingsHelp":
    "**凭证型提供商 Manage（硬 ≥ 0.5.267 / Save 同行 ≥ **0.5.268** / 模型下拉 ≥ **0.5.269** / Save `ghost` `sm` ≥ **0.5.271**）：** 当前 provider 用偏好 `ControlRow` → **需要时**画密码 `FieldBlock`（eye 在 `trailing`）+ **同一行** `.fynns-control-cluster--end-align` — `Input` `fynns-control-cluster__grow` **再** `SaveIcon` IconButton `ghost` `sm`（禁止 tonal/md；禁止 `unit-stack` 甩到输入下方）；已配置用占位提示，保存后清空草稿 → 模型用 `FieldBlock` + `DropdownMenu` `__grow` + 刷新 sm（**禁止**模型可选 `List` 墙；新 UI 勿用软废弃 `Select`）→ 失败 `InlineAlert`（成功静默）→ 一条验证。**禁止**用「未设置/添加」连接态或 Dialog 取代密钥输入，也禁止全提供商 OK/Fail 墙。失败：CONSUMER_TREATY provider Manage flat dump；FieldBlock Save IconButton wraps under Input。对照 `#provider-settings`。",
  "globals.providerSettingsActive": "提供商",
